// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)

	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)

	// (GET /v1/coverage)
	Coverage(ctx context.Context, request CoverageRequestObject) (CoverageResponseObject, error)
	// Hotspots Statistical wildlife collision hotspots along road network
	// (GET /v1/hotspots)
	Hotspots(ctx context.Context, request HotspotsRequestObject) (HotspotsResponseObject, error)
	// Mitigation Wildlife mitigation candidate project sites ranked by benefit-cost ratio
	// (GET /v1/mitigation)
	Mitigation(ctx context.Context, request MitigationRequestObject) (MitigationResponseObject, error)
	// MitigationBriefPDF FHWA WCPP funding-ready PDF brief for a mitigation candidate site
	// (GET /v1/mitigation/{id}/brief.pdf)
	MitigationBriefPDF(ctx context.Context, request MitigationBriefPDFRequestObject) (MitigationBriefPDFResponseObject, error)
	// CreateReport Submit field carcass observation report
	// (POST /v1/reports)
	CreateReport(ctx context.Context, request CreateReportRequestObject) (CreateReportResponseObject, error)
	// UploadReportPhoto Upload carcass observation photo
	// (POST /v1/reports/{id}/photo)
	UploadReportPhoto(ctx context.Context, request UploadReportPhotoRequestObject) (UploadReportPhotoResponseObject, error)
	// Segments Road segments with predicted risk and percentiles
	// (GET /v1/segments)
	Segments(ctx context.Context, request SegmentsRequestObject) (SegmentsResponseObject, error)
	// SegmentDetail Road segment risk detail, monthly profile, and SHAP drivers
	// (GET /v1/segments/{id})
	SegmentDetail(ctx context.Context, request SegmentDetailRequestObject) (SegmentDetailResponseObject, error)

	// (GET /v1/sources)
	Sources(ctx context.Context, request SourcesRequestObject) (SourcesResponseObject, error)
	// StreamReports Real-time SSE stream of incoming carcass reports
	// (GET /v1/stream/reports)
	StreamReports(ctx context.Context, request StreamReportsRequestObject) (StreamReportsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

